const gameHtml = "<!DOCTYPE html><html lang=\"es\"><head>\n<meta charset=\"utf-8\">\n<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\">\n<title>Rescatando a Pulgarcito - Cuaderno de Campo Botánico</title>\n<link href=\"https://fonts.googleapis.com\" rel=\"preconnect\">\n<link crossorigin=\"\" href=\"https://fonts.gstatic.com\" rel=\"preconnect\">\n<link href=\"https://fonts.googleapis.com/css2?family=Special+Elite&amp;family=Patrick+Hand&amp;family=Plus+Jakarta+Sans:wght@500;700;800&amp;family=Comfortaa:wght@700&amp;display=swap\" rel=\"stylesheet\">\n<link href=\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdn.tailwindcss.com?plugins=forms,container-queries\"></script>\n<script id=\"tailwind-config\">\n    tailwind.config = {\n      darkMode: \"class\",\n      theme: {\n        extend: {\n          colors: {\n            parchment: \"#f8f2e6\",\n            \"parchment-deep\": \"#ebd9c0\",\n            \"leather-dark\": \"#2b170c\",\n            \"leather-med\": \"#4e2c17\",\n            \"leather-warm\": \"#7a4623\",\n            brass: \"#d8a63f\",\n            \"brass-dark\": \"#8c6519\",\n            ink: \"#2c221a\",\n            \"ink-faded\": \"#5c5045\",\n            blueprint: \"#1a4659\",\n            \"blueprint-line\": \"#367591\"\n          },\n          fontFamily: {\n            vintage: ['\"Special Elite\"', 'cursive', 'serif'],\n            handwritten: ['\"Patrick Hand\"', 'cursive', 'sans-serif'],\n            sans: ['\"Plus Jakarta Sans\"', 'sans-serif'],\n            comfortaa: ['\"Comfortaa\"', 'cursive']\n          }\n        }\n      }\n    }\n  </script>\n<style>\n    /* Wooden Table Desk Surface */\n    body {\n      background-color: #211209;\n      background-image: \n        radial-gradient(ellipse at 50% 20%, rgba(255,225,180,0.09) 0%, rgba(0,0,0,0.7) 100%),\n        repeating-linear-gradient(90deg, #2b170c 0px, #2b170c 70px, #24130a 71px, #321c10 140px);\n      min-height: 100vh;\n      overflow-x: hidden;\n    }\n\n    /* Topographic Grid / Paper */\n    .blueprint-grid {\n      background-image: \n        radial-gradient(circle at 50% 50%, rgba(44,36,28,0.05) 1px, transparent 1px),\n        linear-gradient(to right, rgba(78,44,23,0.06) 1px, transparent 1px),\n        linear-gradient(to bottom, rgba(78,44,23,0.06) 1px, transparent 1px);\n      background-size: 20px 20px, 20px 20px, 20px 20px;\n    }\n\n    /* Wood Planks */\n    .plank-wood-5 {\n      background: linear-gradient(180deg, #5c3216 0%, #caa06d 12%, #deb782 50%, #b88a53 88%, #4a250e 100%);\n      box-shadow: inset 0 2px 4px rgba(255,255,255,0.7), inset 0 -3px 5px rgba(50,22,6,0.6), 0 6px 14px rgba(0,0,0,0.25);\n    }\n    .plank-wood-10 {\n      background: linear-gradient(180deg, #642813 0%, #d86b36 12%, #e58752 50%, #b85022 88%, #4a1908 100%);\n      box-shadow: inset 0 2px 4px rgba(255,255,255,0.75), inset 0 -3px 5px rgba(60,15,4,0.6), 0 8px 18px rgba(0,0,0,0.28);\n    }\n    .plank-wood-15 {\n      background: linear-gradient(180deg, #381f0f 0%, #7d4d29 12%, #956239 50%, #683a1b 88%, #2d1609 100%);\n      box-shadow: inset 0 2px 4px rgba(255,255,255,0.55), inset 0 -4px 6px rgba(10,5,2,0.8), 0 10px 24px rgba(0,0,0,0.4);\n    }\n\n    /* Floating Clouds */\n    @keyframes cloudDrift {\n      0% { transform: translateX(-20px); }\n      50% { transform: translateX(25px); }\n      100% { transform: translateX(-20px); }\n    }\n    .animate-cloud-slow {\n      animation: cloudDrift 14s ease-in-out infinite;\n    }\n    .animate-cloud-fast {\n      animation: cloudDrift 9s ease-in-out infinite reverse;\n    }\n\n    /* Walking Bobbing Animation */\n    @keyframes walkingBobEffect {\n      0%, 100% { transform: translateY(0px) rotate(0deg); }\n      25% { transform: translateY(-7px) rotate(-2deg); }\n      50% { transform: translateY(0px) rotate(0deg); }\n      75% { transform: translateY(-7px) rotate(2deg); }\n    }\n    .walking-bob {\n      animation: walkingBobEffect 0.28s infinite ease-in-out;\n    }\n\n    /* Slip & Shock Before Fall */\n    @keyframes slipStart {\n      0% { transform: translate3d(var(--fall-x, 140px), 0px, 0px) rotate(0deg); }\n      35% { transform: translate3d(calc(var(--fall-x, 140px) + 15px), -12px, 0px) rotate(15deg) scale(1.05); }\n      60% { transform: translate3d(calc(var(--fall-x, 140px) + 20px), 25px, 0px) rotate(25deg); }\n      100% { transform: translate3d(calc(var(--fall-x, 140px) + 30px), 360px, 0px) rotate(45deg); opacity: 0; }\n    }\n    .char-slip-fall {\n      animation: slipStart 0.95s cubic-bezier(0.55, 0.055, 0.675, 0.19) forwards !important;\n    }\n\n    /* Victory Continuous Jumping / Dance at Camp B */\n    @keyframes jumpJoyContinuous {\n      0%, 100% { transform: translateY(0) scale(1) rotate(0deg); }\n      25% { transform: translateY(-22px) scale(1.06) rotate(-3deg); }\n      50% { transform: translateY(-28px) scale(1.1) rotate(3deg); }\n      75% { transform: translateY(-10px) scale(1.03) rotate(-2deg); }\n    }\n    .char-victory-dance {\n      animation: jumpJoyContinuous 0.65s infinite ease-in-out !important;\n    }\n\n    /* Fall Animation into Chasm */\n    @keyframes freeFallToAbyss {\n      0% {\n        transform: translate3d(var(--fall-x, 260px), var(--fall-y, 0px), 0px) rotate(0deg);\n        opacity: 1;\n      }\n      20% {\n        transform: translate3d(calc(var(--fall-x, 260px) + 14px), calc(var(--fall-y, 0px) + 30px), 0px) rotate(18deg);\n      }\n      50% {\n        transform: translate3d(calc(var(--fall-x, 260px) + 28px), calc(var(--fall-y, 0px) + 150px), 0px) rotate(38deg);\n        opacity: 0.9;\n      }\n      100% {\n        transform: translate3d(calc(var(--fall-x, 260px) + 40px), 380px, 0px) rotate(65deg);\n        opacity: 0;\n      }\n    }\n    .char-abyss-fall {\n      animation: freeFallToAbyss 1.05s cubic-bezier(0.55, 0.055, 0.675, 0.19) forwards !important;\n    }\n\n    /* Synchronized Plank Slide and Fall with Board (Case 15cm diagonal tilt collapse) */\n    @keyframes plankDiagonalCollapse {\n      0% {\n        transform: rotate(-21deg) translateY(0);\n        opacity: 1;\n      }\n      25% {\n        transform: rotate(-14deg) translateY(10px);\n      }\n      50% {\n        transform: rotate(38deg) translate3d(30px, 90px, 0);\n      }\n      100% {\n        transform: rotate(88deg) translate3d(70px, 420px, 0);\n        opacity: 0;\n      }\n    }\n    .plank-abyss-fall {\n      animation: plankDiagonalCollapse 1.1s cubic-bezier(0.55, 0.055, 0.675, 0.19) forwards !important;\n    }\n\n    /* Campfire flickering */\n    @keyframes fireFlicker {\n      0%, 100% { transform: scale(1) rotate(-1deg); opacity: 0.95; }\n      50% { transform: scale(1.15) rotate(2deg); opacity: 1; filter: drop-shadow(0 0 8px #ff7700); }\n    }\n    .animate-fire {\n      animation: fireFlicker 0.6s infinite ease-in-out alternate;\n    }\n\n    /* Confetti Particle Burst */\n    @keyframes confettiFall {\n      0% { transform: translateY(-40px) rotate(0deg) scale(0.8); opacity: 1; }\n      100% { transform: translateY(320px) rotate(720deg) scale(1.2); opacity: 0; }\n    }\n    .confetti-piece {\n      position: absolute;\n      width: 10px;\n      height: 10px;\n      animation: confettiFall 2.2s ease-out forwards;\n    }\n\n    /* Sparkle Particle */\n    @keyframes sparkleGlow {\n      0%, 100% { transform: scale(0) rotate(0deg); opacity: 0; }\n      50% { transform: scale(1.4) rotate(90deg); opacity: 1; filter: drop-shadow(0 0 8px #ffd700); }\n    }\n    .sparkle-dot {\n      position: absolute;\n      animation: sparkleGlow 1.2s infinite ease-in-out;\n    }\n\n    /* Cliff Mirroring */\n    .cliff-mirror {\n      transform: scaleX(-1);\n    }\n\n    html {\n      height: 100% !important;\n      overflow: hidden !important;\n    }\n    body {\n      height: auto !important;\n      min-height: 0 !important;\n      overflow: visible !important;\n      padding: 6px !important;\n    }\n\n    /* En telefonos y tabletas el tablero se ve a tamano real y la pagina se desliza. */\n    @media (max-width: 1100px), (pointer: coarse) {\n      html {\n        height: 100% !important;\n        overflow: hidden !important;\n      }\n      body {\n        height: 100% !important;\n        min-height: 0 !important;\n        max-height: 100% !important;\n        overflow-x: hidden !important;\n        overflow-y: auto !important;\n        -webkit-overflow-scrolling: touch;\n        touch-action: pan-y;\n        overscroll-behavior-y: contain;\n      }\n      body > * {\n        flex-shrink: 0 !important;\n      }\n    }\n  </style>\n</head>\n<body class=\"font-sans text-ink p-2 sm:p-4 md:p-6 flex flex-col items-center justify-start min-h-screen\">\n<!-- TOP EXPEDITION HEADER / FIELD DESK BAR -->\n<header class=\"w-full max-w-[1760px] mb-1 bg-leather-dark/95 backdrop-blur-md border-2 border-brass/50 rounded-2xl px-4 py-2.5 shadow-2xl flex flex-wrap items-center justify-between gap-3 text-parchment\">\n<div class=\"flex items-center gap-3\">\n<div class=\"w-11 h-11 rounded-xl bg-gradient-to-br from-brass to-brass-dark text-leather-dark flex items-center justify-center font-vintage text-2xl font-bold shadow-md border border-parchment/30 select-none\">\n      🧭\n    </div>\n<div>\n<div class=\"flex items-center gap-2\">\n<span class=\"font-vintage text-xs uppercase tracking-widest text-brass font-bold\" id=\"field-number\">Cuaderno de Campo Nº 102</span>\n<span class=\"px-2 py-0.5 text-[10px] uppercase font-bold tracking-wider rounded-md bg-brass-dark/80 text-parchment border border-brass/30\">Expedición Botánica</span>\n</div>\n<h1 class=\"font-vintage text-lg md:text-xl font-black text-parchment tracking-wide flex items-center gap-2\"><span class=\"\">¡Rescata a Pulgarcito!</span> <span class=\"text-xs text-brass font-normal font-sans tracking-normal opacity-90 hidden sm:inline\" id=\"level-subtitle\">• Paso de Roca 10 cm</span></h1>\n</div>\n</div>\n<!-- Desk Tools & Audio Controls -->\n<div class=\"flex items-center gap-3\">\n<button class=\"flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-leather-med border border-brass/40 text-parchment hover:bg-leather-warm transition-all text-xs font-vintage font-bold shadow-sm cursor-pointer\" id=\"audio-toggle-btn\" type=\"button\">\n<span class=\"material-symbols-outlined text-sm text-brass\" id=\"audio-icon\">volume_up</span>\n<span class=\"\" id=\"audio-text\">Audio ON</span>\n</button>\n<button class=\"flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-leather-med border border-brass/40 text-parchment hover:bg-leather-warm active:scale-95 transition-all text-xs font-vintage font-bold shadow-sm cursor-pointer\" id=\"btn-top-reset\" onclick=\"resetExpedition()\" title=\"Reiniciar tablero\" type=\"button\">\n<span class=\"material-symbols-outlined text-sm text-brass\">restart_alt</span>\n<span class=\"hidden sm:inline\">Reiniciar</span>\n</button>\n</div>\n</header>\n<!-- MAIN STACKED WORKSPACE: FULL WIDTH TOP STAGE + HORIZONTAL BOTTOM WOOD RACK -->\n<main class=\"w-full max-w-[1760px] flex flex-col gap-2 items-stretch justify-center\">\n<!-- A) ARRIBA: LA ZONA DE ANIMACIÓN DEL JUEGO -->\n<section class=\"w-full bg-parchment rounded-2xl p-2 sm:p-3 shadow-2xl border-4 border-leather-med relative flex flex-col justify-between overflow-hidden blueprint-grid\">\n<!-- Top Prompt Banner & Navigation Compass -->\n<div class=\"flex flex-wrap sm:flex-nowrap items-start justify-between gap-3 relative z-20 pb-3 border-b-2 border-leather-med/20\">\n<div>\n<div class=\"flex items-center gap-2\">\n<span class=\"w-3.5 h-3.5 rounded-full bg-red-600 shadow-md border-2 border-red-900 inline-block animate-pulse\"></span>\n<span class=\"font-vintage text-xs uppercase text-leather-warm font-bold tracking-wider\">Vista Lateral 2D • Escala 1:1</span>\n</div>\n<h2 class=\"font-vintage text-xl sm:text-2xl lg:text-3xl text-leather-dark font-extrabold mt-0.5\" id=\"level-title\">¡Rescata a Pulgarcito cruzando la grieta de 10 cm!</h2>\n</div>\n<!-- Nautical Compass -->\n<div class=\"w-14 h-14 sm:w-16 sm:h-16 rounded-full bg-parchment-deep border-2 border-brass-dark shadow-md flex items-center justify-center relative shrink-0 self-start\">\n<div class=\"absolute inset-1 rounded-full border border-dashed border-leather-med/40\"></div>\n<span class=\"absolute top-0.5 text-[8px] font-vintage font-bold text-red-700\">N</span>\n<span class=\"absolute bottom-0.5 text-[8px] font-vintage font-bold text-ink-faded\">S</span>\n<span class=\"absolute left-1 text-[8px] font-vintage font-bold text-ink-faded\">O</span>\n<span class=\"absolute right-1 text-[8px] font-vintage font-bold text-ink-faded\">E</span>\n<div class=\"w-8 h-8 sm:w-9 sm:h-9 rounded-full border border-brass flex items-center justify-center rotate-45 shadow-sm\">\n<div class=\"w-1.5 h-7 sm:h-8 bg-gradient-to-b from-red-600 via-white to-ink rounded-full\"></div>\n</div>\n</div>\n</div>\n<!-- PROTAGONIST EXPEDITION SCENERY (WIDE EXPEDITION STAGE CON PAISAJE VIOLETA ATARDECER) -->\n<div class=\"relative w-full border-3 border-blueprint-line/50 rounded-2xl overflow-hidden shadow-2xl flex flex-col justify-end p-2 sm:p-4 my-2 min-h-[500px]\" style=\"background-image: url('/images/semana1/paisaje1.jpg'); background-size: cover; background-position: center center; background-repeat: no-repeat;\">\n<!-- Topographical Sky with Drifting Adventure Clouds -->\n<div class=\"absolute inset-0 pointer-events-none overflow-hidden\">\n<!-- Sun Rays Glow -->\n<div class=\"absolute -top-12 left-1/3 w-96 h-96 bg-amber-100/20 rounded-full blur-3xl pointer-events-none\"></div>\n<!-- Drifting Clouds -->\n<div class=\"absolute top-6 left-14 text-white/80 animate-cloud-slow flex items-center gap-1\">\n<svg class=\"w-28 h-12\" fill=\"currentColor\" viewBox=\"0 0 100 50\">\n<path d=\"M20 40 A15 15 0 0 1 35 15 A22 22 0 0 1 70 18 A16 16 0 0 1 85 40 Z\"></path>\n</svg>\n</div>\n<div class=\"absolute top-12 right-28 text-white/70 animate-cloud-fast flex items-center gap-1\">\n<svg class=\"w-32 h-14\" fill=\"currentColor\" viewBox=\"0 0 100 50\">\n<path d=\"M18 42 A14 14 0 0 1 32 18 A20 20 0 0 1 68 20 A15 15 0 0 1 82 42 Z\"></path>\n</svg>\n</div>\n</div>\n<!-- Distance Callout Pin Overlay -->\n<div class=\"absolute top-3 left-1/2 -translate-x-1/2 z-30 flex items-center gap-2 bg-leather-dark/90 px-4 py-1.5 rounded-full border-2 border-brass shadow-lg backdrop-blur-sm\">\n<span class=\"material-symbols-outlined text-base text-brass\">straighten</span>\n<span class=\"font-vintage text-xs sm:text-sm font-black text-parchment\">Brecha a Cubrir: <span class=\"text-amber-300 font-extrabold tracking-wide drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]\" id=\"gap-banner\">10 cm EXACTOS</span></span>\n</div>\n<!-- Confetti & Sparkles Overlay Container -->\n<div class=\"absolute inset-0 pointer-events-none z-50 overflow-hidden\" id=\"confetti-box\"></div>\n<!-- 2D STAGE WRAPPER: NATURAL BOTANICAL CLIFF GAP -->\n<div class=\"w-full h-400px relative flex items-end justify-between z-20 min-h-[400px]\" id=\"adventure-stage\">\n<!-- 1) RISCO A (CLIFF A - LEFT) -->\n<div class=\"relative w-[34%] max-w-[460px] h-full flex flex-col justify-end z-30\" id=\"cliff-a-zone\">\n<div class=\"w-full h-56 relative select-none pointer-events-none drop-shadow-xl overflow-visible\">\n<img alt=\"Acantilado Risco A\" class=\"w-full h-full object-cover object-left-bottom\" src=\"/images/semana1/acantilado.png\">\n</div>\n</div>\n<!-- 2) GAP & BRIDGE SYSTEM (CENTER CHASM - 10 CM BRECHA) -->\n<div class=\"relative flex-1 max-w-[760px] mx-1 sm:mx-3 h-full flex flex-col justify-end items-center pb-2 overflow-visible\" id=\"bridge-zone\">\n<!-- Distance Guide Label & Dashed Indicator Line -->\n<div class=\"w-full flex items-center justify-between mb-2 px-1 relative z-30 pointer-events-none\">\n<span class=\"w-3.5 h-3.5 border-l-2 border-b-2 border-amber-300\"></span>\n<div class=\"flex-1 border-b-2 border-dashed border-amber-300/80 flex items-center justify-center\">\n<span class=\"bg-leather-dark/95 px-3.5 py-1 rounded-full font-vintage text-base sm:text-lg font-black text-white shadow-xl border-2 border-brass/60 drop-shadow-[0_2px_4px_rgba(0,0,0,0.9)]\" id=\"gap-label\">10 cm exactos</span>\n</div>\n<span class=\"w-3.5 h-3.5 border-r-2 border-b-2 border-amber-300\"></span>\n</div>\n<!-- Bridge Placement Receiver Slot (Aligned at cliff edge) -->\n<div class=\"w-full h-14 border-3 border-dashed border-amber-300/70 bg-black/30 backdrop-blur-[2px] rounded-xl flex items-center justify-start relative px-0 shadow-inner z-25 mb-1.5 overflow-visible\" id=\"bridge-slot\">\n<div class=\"w-full text-center font-vintage text-xs sm:text-sm text-white font-bold pointer-events-none flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg bg-leather-dark/95 border border-brass/50 shadow-xl drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] mx-2\" id=\"slot-guide-text\"><span class=\"material-symbols-outlined text-lg text-amber-300 animate-bounce\">unarchive</span><span class=\"text-white font-black tracking-wide\">Coloca aquí la madera seleccionada abajo</span></div>\n<!-- MOUNTED 2D WOOD PLANK ON THE GAP (Proporcional: 5cm = 50%, 10cm = 100% horizontal, 15cm = 155% diagonal inclinada estilo referencia https://lh3.googleusercontent.com/aida-public/AB6AXuBMU7jIbVCWMqBQ_SzVcQU2HMBQ8I63iEcD1UawXtsJaSiFVJ5rJHh4YjWjMu4x2IYeH1EPDJhb0NCuW_UP2mr9ufksMk5XnsgaSioOp2Dyg6gV5VeT4yF6hrOmxo67VFBMXIdBCfbrl3uHdJKXB3lzu-mzC-eioBtg430ERznR7wB9eaZNeo74tHpoxAQM7SbRt1MQjfkiwRfFun9-H8dz8TUlXB2N_m8eNjqw7UL0LiV9dWICUz4tPdj4I3AyuI4Q4g) -->\n<div class=\"h-11 rounded-lg flex items-center justify-between px-3 text-xs sm:text-sm font-vintage font-black shadow-lg transition-all duration-300 relative z-30 overflow-visible text-[#f2dac2] origin-bottom-left ring-2 plank-wood-10 text-parchment ring-brass ring-4 shadow-[0_0_35px_#d8a63f]\" id=\"active-bridge-board\" style=\"opacity: 1; width: 100%; transform: rotate(0deg);\">\n<span class=\"w-2.5 h-2.5 rounded-full bg-brass border border-black shadow shrink-0\"></span>\n<span class=\"drop-shadow tracking-wider text-white font-black text-center whitespace-nowrap px-1\" id=\"active-board-title\">Tablón Cedro 10 cm</span>\n<span class=\"px-2 py-0.5 rounded text-[11px] font-bold bg-emerald-500 text-white\" id=\"active-board-stamp\">⭐ 10 cm (Horizontal Exacta)</span>\n<span class=\"w-2.5 h-2.5 rounded-full bg-brass border border-black shadow shrink-0\"></span>\n</div>\n</div>\n<!-- Abyss Depth -->\n<div class=\"w-full h-36 relative flex flex-col justify-end items-center overflow-hidden rounded-b-xl pointer-events-none\">\n</div>\n</div>\n<!-- 3) RISCO B (CLIFF B - RIGHT / CAMPAMENTO) -->\n<div class=\"relative w-[34%] max-w-[460px] h-full flex flex-col justify-end z-30\" id=\"cliff-b-zone\">\n<!-- Explorer Tent & Campfire -->\n<div class=\"flex items-end gap-2 mb-[-8px] mr-4 sm:mr-8 self-end z-30 relative\" id=\"tent-camp\">\n<svg class=\"w-16 h-14 sm:w-20 sm:h-16 drop-shadow-md\" viewBox=\"0 0 70 60\">\n<polygon fill=\"#d8a63f\" points=\"35,6 6,54 64,54\" stroke=\"#7a4623\" stroke-width=\"2.5\"></polygon>\n<polygon fill=\"#573318\" points=\"35,6 28,54 42,54\"></polygon>\n<line stroke=\"#362012\" stroke-width=\"2.5\" x1=\"35\" x2=\"35\" y1=\"2\" y2=\"56\"></line>\n<polygon fill=\"#c0392b\" points=\"35,6 58,2 58,14\"></polygon>\n<circle cx=\"35\" fill=\"#f8f2e6\" r=\"3\"></circle>\n</svg>\n<div class=\"flex flex-col items-center\">\n<span class=\"text-3xl animate-fire filter select-none\">🔥</span>\n<span class=\"text-sm -mt-2 select-none\">🪵</span>\n</div>\n</div>\n<div class=\"w-full h-56 relative select-none pointer-events-none drop-shadow-xl overflow-visible cliff-mirror\">\n<img alt=\"Acantilado Risco B\" class=\"w-full h-full object-cover object-left-bottom\" src=\"/images/semana1/acantilado.png\">\n</div>\n</div>\n<!-- PULGARCITO EXPLORER CHARACTER -->\n<div class=\"absolute z-40 origin-bottom bottom-[180px]\" id=\"pulgarcito-char\" style=\"left: 35px; transform: translate3d(0px, 0px, 0px); transition: none; opacity: 1;\">\n<!-- Vector Explorer Container -->\n<div class=\"transition-transform\" id=\"pulgarcito-bobber\">\n<img alt=\"Explorador Pulgarcito\" class=\"object-contain drop-shadow-xl select-none pointer-events-none transition-all duration-200 w-36 h-56 sm:w-44 sm:h-72 w-40 h-60 sm:w-48 sm:h-76\" id=\"pulgarcito-img\" src=\"/images/semana1/exploradorCelebrando.png\" style=\"transform: none;\">\n</div>\n</div>\n</div>\n</div>\n<!-- PANEL EXPLICATIVO FIJO DEBAJO DE LOS ACANTILADOS -->\n<div class=\"w-full mt-2.5 rounded-2xl p-3.5 transition-all duration-300 border-2 flex items-center gap-3.5 shadow-md relative z-20 bg-emerald-50 border-emerald-600/70 text-emerald-950 ring-2 ring-emerald-400/40\" id=\"cliff-explanation-bar\">\n<div class=\"w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-inner border bg-emerald-200/90 border-emerald-400 text-emerald-900\" id=\"explanation-icon-wrapper\">\n<span class=\"text-2xl select-none\" id=\"explanation-icon\">🎉</span>\n</div>\n<div class=\"flex-1 min-w-0\">\n<div class=\"flex items-center gap-2\">\n<span class=\"font-vintage text-xs uppercase tracking-wider font-extrabold text-emerald-800\" id=\"explanation-badge\">¡Avanzando a Nivel 2!</span>\n<span class=\"text-[11px] font-handwritten px-2 py-0.2 rounded-full bg-parchment-deep border border-leather-med/30 text-leather-dark font-bold hidden sm:inline\" id=\"explanation-subtag\">¡Cruce Exitoso!</span>\n</div>\n<p class=\"font-handwritten text-sm sm:text-base leading-snug mt-0.5 text-leather-dark font-semibold\" id=\"explanation-text\">¡Excelente botánico! Has conquistado El Risco del Paso Estrecho. Preparando la siguiente expedición botánica...</p>\n</div>\n</div>\n</section>\n<!-- B) ABAJO: PANEL HORIZONTAL DE TABLAS DE MADERA Y ACCIONES DE CRUCE -->\n<section class=\"w-full bg-parchment-deep rounded-2xl p-2 sm:p-3 shadow-2xl border-4 border-leather-med flex flex-col gap-4 relative z-30\">\n<!-- Header of the wood selection rack -->\n<div class=\"flex flex-wrap items-center justify-between border-b-2 border-leather-med/30 pb-3 gap-2\">\n<div>\n<div class=\"flex items-center gap-2\">\n<span class=\"font-vintage text-xs uppercase tracking-wider text-leather-warm font-black flex items-center gap-1\">Vista Lateral 2D • Escala 1:1</span>\n<span class=\"bg-leather-med text-parchment text-[11px] font-vintage px-2.5 py-0.5 rounded-full font-bold shadow-sm\" id=\"rack-count\">3 Maderas Disponibles</span>\n</div>\n<h3 class=\"font-vintage text-xl sm:text-2xl font-black text-leather-dark mt-0.5\">\n          Compara y Selecciona la Madera\n        </h3>\n</div>\n<p class=\"font-handwritten text-base sm:text-lg text-ink-faded\" id=\"rack-hint\">Toca la madera con la medida exacta para cubrir los <strong class=\"text-leather-dark underline decoration-brass\">10 cm</strong>:</p>\n</div>\n<!-- 3 WOOD PLANK CARDS ORGANIZED IN A HORIZONTAL GRID -->\n<div class=\"grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 relative z-30\" id=\"plank-grid\">\n<!-- OPTION 1: 5 cm (Tablilla Ligera de Pino - 50% mitad) -->\n<div class=\"plank-option group cursor-pointer rounded-2xl p-4 border-2 shadow-md hover:shadow-xl hover:border-leather-warm hover:scale-[1.01] transition-all active:scale-[0.99] flex flex-col justify-between gap-3 relative select-none border-leather-med/50 bg-parchment\" data-cm=\"5\" id=\"opt-plank-5\" onclick=\"choosePlank(5)\">\n<div class=\"flex items-center justify-between pointer-events-none\">\n<div class=\"flex items-center gap-2\"><span class=\"w-7 h-7 rounded-full bg-parchment-deep border border-leather-med text-leather-dark font-vintage text-xs font-black flex items-center justify-center shadow-sm\">1</span><span class=\"text-lg select-none\" title=\"Tronco de pino\">🪵</span><span class=\"font-bold text-sm sm:text-base text-leather-dark font-sans\">Tablilla de Pino</span></div>\n<span class=\"px-2.5 py-0.5 rounded-md bg-amber-100 border border-amber-500 font-vintage text-xs font-black text-amber-950 shadow-inner\">\n            5 cm\n          </span>\n</div>\n<!-- Visual proportional plank sample (50% width) -->\n<div class=\"w-full h-9 bg-[#ebd2b5]/70 rounded-xl p-2 flex items-center border border-leather-med/30 shadow-inner pointer-events-none\">\n<div class=\"w-[50%] h-full plank-wood-5 rounded-lg border-2 border-[#5c3216] flex items-center justify-between px-3 text-leather-dark relative overflow-hidden shadow-md\">\n<span class=\"w-2 h-2 rounded-full bg-[#fce49f] border border-[#6b3e14] shadow-sm\"></span>\n<span class=\"font-vintage text-xs font-black text-[#381c07] drop-shadow-[0_1px_1px_rgba(255,255,255,0.7)]\">\n              5 cm\n            </span>\n<span class=\"w-2 h-2 rounded-full bg-[#fce49f] border border-[#6b3e14] shadow-sm\"></span>\n</div>\n<span class=\"ml-3 font-handwritten text-xs sm:text-sm text-red-800 font-bold\">¡Le falta la mitad!</span>\n</div>\n<div class=\"flex items-center justify-between text-xs font-handwritten text-red-800 pt-1 border-t border-leather-med/20 pointer-events-none\">\n<span class=\"\">Quedará hueco de 5 cm</span>\n<span class=\"status-tag font-vintage font-bold text-leather-med group-hover:underline\">Elegir ➔</span>\n</div>\n</div>\n<!-- OPTION 2: 10 cm (Tablón de Cedro Reforzado - EXACT MATCH 100% HORIZONTAL) -->\n<div class=\"plank-option group cursor-pointer rounded-2xl p-4 border-2 shadow-md hover:shadow-xl hover:border-brass-dark hover:scale-[1.01] transition-all active:scale-[0.99] flex flex-col justify-between gap-3 relative ring-2 ring-transparent select-none ring-4 ring-emerald-500 bg-emerald-100/80 border-emerald-700 shadow-2xl scale-[1.02]\" data-cm=\"10\" id=\"opt-plank-10\" onclick=\"choosePlank(10)\">\n<!-- Gold Star Pill -->\n<div class=\"absolute -top-2.5 right-4 bg-gradient-to-r from-brass to-amber-400 text-leather-dark font-vintage text-[11px] font-black px-2.5 py-0.5 rounded-full border border-leather-dark shadow-md flex items-center gap-1 pointer-events-none\">\n<span class=\"\">⭐</span> Medida Exacta\n        </div>\n<div class=\"flex items-center justify-between pointer-events-none\">\n<div class=\"flex items-center gap-2\"><span class=\"w-7 h-7 rounded-full bg-brass/40 border border-brass-dark text-leather-dark font-vintage text-xs font-black flex items-center justify-center shadow-sm\">2</span><span class=\"text-lg select-none\" title=\"Tronco de cedro\">🪵</span><span class=\"font-bold text-sm sm:text-base text-leather-dark font-sans\">Tablón de Cedro</span></div>\n<span class=\"px-2.5 py-0.5 rounded-md bg-emerald-100 border border-emerald-600 font-vintage text-xs font-black text-emerald-950 shadow-inner\">\n            10 cm\n          </span>\n</div>\n<!-- Visual proportional plank sample (100% horizontal match) -->\n<div class=\"w-full h-14 bg-[#ebd2b5]/70 rounded-xl p-2 flex items-center border border-leather-med/30 shadow-inner pointer-events-none\">\n<div class=\"w-full h-full plank-wood-10 rounded-lg border-2 border-[#541e0a] flex items-center justify-between px-3 text-parchment relative overflow-hidden shadow-md\">\n<div class=\"flex items-center gap-1\">\n<span class=\"w-2 h-2 rounded-full bg-amber-200 border border-black shadow-sm\"></span>\n<span class=\"text-[9px] font-vintage text-amber-200 font-bold hidden sm:inline\">0 cm</span>\n</div>\n<span class=\"font-vintage text-xs sm:text-sm font-black text-amber-100 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] tracking-wide\">\n              ⭐ 10 cm (Horizontal Exacta)\n            </span>\n<div class=\"flex items-center gap-1\">\n<span class=\"text-[9px] font-vintage text-amber-200 font-bold hidden sm:inline\">10 cm</span>\n<span class=\"w-2 h-2 rounded-full bg-amber-200 border border-black shadow-sm\"></span>\n</div>\n</div>\n</div>\n<div class=\"flex items-center justify-between text-xs font-handwritten text-emerald-900 font-bold pt-1 border-t border-leather-med/20 pointer-events-none\">\n<span class=\"\">¡Calza exacta sin faltar ni sobrar!</span>\n<span class=\"status-tag font-vintage font-bold text-leather-med group-hover:underline\">✓ Seleccionada</span>\n</div>\n</div>\n<!-- OPTION 3: 15 cm (Viga Maciza de Roble - OVERSIZED 150%-160% DIAGONAL INCLINADA SEGÚN REFERENCIA) -->\n<div class=\"plank-option group cursor-pointer rounded-2xl p-4 border-2 shadow-md hover:shadow-xl hover:border-leather-dark hover:scale-[1.01] transition-all active:scale-[0.99] flex flex-col justify-between gap-3 relative select-none border-leather-med/50 bg-parchment\" data-cm=\"15\" id=\"opt-plank-15\" onclick=\"choosePlank(15)\">\n<div class=\"flex items-center justify-between pointer-events-none\">\n<div class=\"flex items-center gap-2\"><span class=\"w-7 h-7 rounded-full bg-parchment-deep border border-leather-med text-leather-dark font-vintage text-xs font-black flex items-center justify-center shadow-sm\">3</span><span class=\"text-xl select-none\" title=\"Tronco grueso de roble\">🪵</span><span class=\"font-bold text-sm sm:text-base text-leather-dark font-sans\">Viga Maciza de Roble</span></div>\n<span class=\"px-2.5 py-0.5 rounded-md bg-rose-100 border border-rose-500 font-vintage text-xs font-black text-rose-950 shadow-inner\">\n            15 cm\n          </span>\n</div>\n<!-- Visual proportional plank sample (Claramente más larga y en diagonal hacia arriba a la derecha como en el boceto de referencia) -->\n<div class=\"w-full h-14 bg-[#ebd2b5]/70 rounded-xl p-2 flex items-center border border-leather-med/30 shadow-inner overflow-hidden pointer-events-none relative\"><div class=\"w-full h-full plank-wood-15 rounded-lg border-4 border-[#2b170c] flex items-center justify-between px-3 text-[#f2dac2] relative overflow-hidden shadow-lg ring-1 ring-amber-950/40\"><div class=\"flex items-center gap-1\"><span class=\"w-3 h-3 rounded-full bg-amber-600 border-2 border-black shadow-sm\"></span><span class=\"text-[10px] font-bold text-amber-200 hidden sm:inline font-sans\">0 cm</span></div><span class=\"font-black text-xs sm:text-sm text-amber-100 drop-shadow-[0_2px_3px_rgba(0,0,0,0.9)] tracking-wide font-sans flex items-center gap-1.5\"><span class=\"\">🪵</span> 15 cm ⚠️ (Roble Grueso / Sobresale 5 cm)</span><div class=\"flex items-center gap-1\"><span class=\"text-[10px] font-bold text-amber-200 hidden sm:inline font-sans\">15 cm</span><span class=\"w-3 h-3 rounded-full bg-amber-600 border-2 border-black shadow-sm\"></span></div></div></div>\n<div class=\"flex items-center justify-between text-xs font-handwritten text-rose-900 font-bold pt-1 border-t border-leather-med/20 pointer-events-none\">\n<span class=\"\">Queda inclinada en diagonal y muy empinada</span>\n<span class=\"status-tag font-vintage font-bold text-leather-med group-hover:underline\">Elegir ➔</span>\n</div>\n</div>\n</div>\n<!-- HORIZONTAL ACTION BAR -->\n<div class=\"pt-2 border-t-2 border-leather-med/30 flex flex-col sm:flex-row items-center justify-between gap-4\">\n<div class=\"flex-1 text-xs sm:text-sm font-handwritten text-ink leading-relaxed\" id=\"advice-text\"><span class=\"text-leather-warm font-bold\">Consejo:</span> Observa la distancia de 10 cm y elige la madera que no deje huecos ni sobrepase la roca.</div>\n<!-- Action Buttons Container -->\n<div class=\"w-full sm:w-auto min-w-[320px] flex flex-col sm:flex-row items-stretch sm:items-center justify-end gap-2.5\">\n<!-- Primary Crossing Trigger -->\n<button class=\"w-full sm:w-auto py-3.5 px-6 rounded-2xl bg-leather-med text-parchment font-vintage text-base sm:text-lg font-black shadow-xl border-2 border-brass/50 hover:bg-leather-warm active:scale-98 transition-all flex items-center justify-center gap-2 cursor-pointer\" id=\"btn-cross-expedition\" onclick=\"handleCrossClick()\" type=\"button\">\n<span class=\"material-symbols-outlined text-2xl\">hiking</span>\n<span class=\"\" id=\"btn-cross-label\">Cruzar Expedición</span>\n</button>\n<!-- Botón Siguiente Nivel -->\n<button class=\"w-full sm:w-auto py-3 px-6 rounded-2xl plank-wood-10 text-parchment font-vintage text-base sm:text-lg font-black shadow-2xl border-3 border-[#541e0a] hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2.5 cursor-pointer ring-4 ring-amber-400/40 hidden\" id=\"btn-next-level\" onclick=\"goToNextLevel()\" style=\"display: none;\" type=\"button\">\n<span class=\"text-2xl select-none filter drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]\">🪵</span>\n<span class=\"tracking-wide text-amber-100 drop-shadow-[0_2px_4px_rgba(0,0,0,0.9)]\">¡Siguiente Nivel! ➔</span>\n<span class=\"material-symbols-outlined text-2xl animate-pulse text-amber-300 drop-shadow-md\">arrow_circle_right</span>\n</button>\n\n<button class=\"w-full sm:w-auto py-3 px-5 rounded-2xl bg-leather-med hover:bg-leather-warm text-parchment font-vintage text-sm sm:text-base font-bold shadow-xl border-2 border-brass/40 active:scale-95 transition-all items-center justify-center gap-2 cursor-pointer hidden\" id=\"btn-replay-all\" style=\"display: none;\" type=\"button\">\n<span class=\"material-symbols-outlined text-xl text-brass\">replay</span>\n<span>Volver a jugar</span>\n</button>\n<button class=\"w-full sm:w-auto py-3 px-5 rounded-2xl bg-leather-dark hover:bg-black text-parchment font-vintage text-sm sm:text-base font-bold shadow-xl border-2 border-brass/40 active:scale-95 transition-all items-center justify-center gap-2 cursor-pointer hidden\" id=\"btn-go-home\" style=\"display: none;\" type=\"button\">\n<span class=\"material-symbols-outlined text-xl text-brass\">home</span>\n<span>Volver al inicio</span>\n</button>\n<!-- Botón de Reiniciar Nivel / Jugar de Nuevo -->\n<button class=\"w-full sm:w-auto py-3 px-5 rounded-2xl bg-leather-med hover:bg-leather-warm text-parchment font-vintage text-sm sm:text-base font-bold shadow-xl border-2 border-brass/40 active:scale-95 transition-all flex items-center justify-center gap-2 cursor-pointer\" id=\"btn-restart-action\" onclick=\"resetExpedition()\" style=\"display: none;\" type=\"button\" class=\"hidden\">\n<span class=\"material-symbols-outlined text-xl text-brass\">replay</span>\n<span class=\"\">Reiniciar Nivel</span>\n</button>\n</div>\n</div>\n</section>\n</main>\n<!-- JAVASCRIPT LOGIC & WEB AUDIO SYNTHESIZER -->\n<script>\n  let selectedCm = null;\n  let isMoving = false;\n  let soundEnabled = true;\n  let walkAnimationInterval = null;\n  let autoResetTimer = null;\n  let hasWon = false;\n\n  // Sprites configuration using exact DataStore placeholders\n  const SPRITE_STANDING = \"/images/semana1/explorador.png\";\n  const SPRITE_WALKING = \"/images/semana1/exploradorCaminando.png\";\n  const SPRITE_FALLING = \"/images/semana1/exploradorCallendo.png\";\n  const SPRITE_CELEBRATING = \"/images/semana1/exploradorCelebrando.png\";\n\n  function setCharacterSprite(state) {\n    const img = document.getElementById('pulgarcito-img');\n    if (!img) return;\n    if (state === 'falling' || state === true) {\n      img.src = SPRITE_FALLING;\n      img.style.transform = 'none';\n      img.classList.remove('w-36', 'h-56', 'sm:w-44', 'sm:h-72', 'w-40', 'h-60', 'sm:w-48', 'sm:h-76');\n      img.classList.add('w-44', 'h-64', 'sm:w-52', 'sm:h-80', 'scale-110');\n    } else if (state === 'walking') {\n      img.src = SPRITE_WALKING;\n      img.style.transform = 'none';\n      img.classList.remove('w-44', 'h-64', 'sm:w-52', 'sm:h-80', 'scale-110', 'w-40', 'h-60', 'sm:w-48', 'sm:h-76');\n      img.classList.add('w-36', 'h-56', 'sm:w-44', 'sm:h-72');\n    } else if (state === 'celebrating') {\n      img.src = SPRITE_CELEBRATING;\n      img.style.transform = 'none';\n      img.classList.remove('w-44', 'h-64', 'sm:w-52', 'sm:h-80', 'scale-110');\n      img.classList.add('w-40', 'h-60', 'sm:w-48', 'sm:h-76');\n    } else {\n      // standing / idle\n      img.src = SPRITE_STANDING;\n      img.style.transform = 'none';\n      img.classList.remove('w-44', 'h-64', 'sm:w-52', 'sm:h-80', 'scale-110', 'w-40', 'h-60', 'sm:w-48', 'sm:h-76');\n      img.classList.add('w-36', 'h-56', 'sm:w-44', 'sm:h-72');\n    }\n  }\n\n  // Web Audio Synthesizer\n  let audioContext = null;\n  function initAudio() {\n    if (!audioContext) {\n      const AudioClass = window.AudioContext || window.webkitAudioContext;\n      if (AudioClass) audioContext = new AudioClass();\n    }\n    if (audioContext && audioContext.state === 'suspended') {\n      audioContext.resume();\n    }\n    return audioContext;\n  }\n\n  function emitSound(kind) {\n    if (!soundEnabled) return;\n    try {\n      const ctx = initAudio();\n      if (!ctx) return;\n      const now = ctx.currentTime;\n\n      if (kind === 'wood-thud') {\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'triangle';\n        osc.frequency.setValueAtTime(320, now);\n        osc.frequency.exponentialRampToValueAtTime(80, now + 0.08);\n        gain.gain.setValueAtTime(0.5, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.09);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.09);\n      } else if (kind === 'step') {\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(220, now);\n        osc.frequency.exponentialRampToValueAtTime(110, now + 0.05);\n        gain.gain.setValueAtTime(0.25, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.06);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.06);\n      } else if (kind === 'wood-crack') {\n        const bufferSize = Math.floor(ctx.sampleRate * 0.3);\n        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);\n        const data = buffer.getChannelData(0);\n        for (let i = 0; i < bufferSize; i++) {\n          data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.25));\n        }\n        const noise = ctx.createBufferSource();\n        noise.buffer = buffer;\n        const filter = ctx.createBiquadFilter();\n        filter.type = 'highpass';\n        filter.frequency.setValueAtTime(1200, now);\n        const gain = ctx.createGain();\n        gain.gain.setValueAtTime(0.7, now);\n        noise.connect(filter);\n        filter.connect(gain);\n        gain.connect(ctx.destination);\n        noise.start(now);\n      } else if (kind === 'splash') {\n        const bufferSize = Math.floor(ctx.sampleRate * 0.4);\n        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);\n        const data = buffer.getChannelData(0);\n        for (let i = 0; i < bufferSize; i++) {\n          data[i] = Math.random() * 2 - 1;\n        }\n        const noise = ctx.createBufferSource();\n        noise.buffer = buffer;\n        const filter = ctx.createBiquadFilter();\n        filter.type = 'bandpass';\n        filter.frequency.setValueAtTime(800, now);\n        filter.frequency.linearRampToValueAtTime(300, now + 0.35);\n        const gain = ctx.createGain();\n        gain.gain.setValueAtTime(0.4, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.38);\n        noise.connect(filter);\n        filter.connect(gain);\n        gain.connect(ctx.destination);\n        noise.start(now);\n      } else if (kind === 'fall-whoosh') {\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(380, now);\n        osc.frequency.exponentialRampToValueAtTime(90, now + 0.55);\n        gain.gain.setValueAtTime(0.35, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.58);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.58);\n      } else if (kind === 'comic-slip') {\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'sawtooth';\n        osc.frequency.setValueAtTime(300, now);\n        osc.frequency.exponentialRampToValueAtTime(650, now + 0.12);\n        osc.frequency.exponentialRampToValueAtTime(100, now + 0.45);\n        gain.gain.setValueAtTime(0.45, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.45);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.46);\n      } else if (kind === 'poom') {\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(180, now);\n        osc.frequency.exponentialRampToValueAtTime(45, now + 0.22);\n        gain.gain.setValueAtTime(0.6, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.24);\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.24);\n      } else if (kind === 'sparkle') {\n        [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {\n          const osc = ctx.createOscillator();\n          const gain = ctx.createGain();\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(freq, now + i * 0.07);\n          gain.gain.setValueAtTime(0.3, now + i * 0.07);\n          gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.07 + 0.3);\n          osc.connect(gain);\n          gain.connect(ctx.destination);\n          osc.start(now + i * 0.07);\n          osc.stop(now + i * 0.07 + 0.35);\n        });\n      } else if (kind === 'victory') {\n        const chords = [392.00, 523.25, 659.25, 783.99, 1046.50];\n        chords.forEach((freq, i) => {\n          const osc = ctx.createOscillator();\n          const gain = ctx.createGain();\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(freq, now + i * 0.12);\n          gain.gain.setValueAtTime(0.35, now + i * 0.12);\n          gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.12 + 0.55);\n          osc.connect(gain);\n          gain.connect(ctx.destination);\n          osc.start(now + i * 0.12);\n          osc.stop(now + i * 0.12 + 0.6);\n        });\n      }\n    } catch (err) {\n      console.warn(\"Audio issue\", err);\n    }\n  }\n\n  // Setup event listeners\n  function setupEventListeners() {\n    const audioBtn = document.getElementById('audio-toggle-btn');\n    const audioIcon = document.getElementById('audio-icon');\n    const audioText = document.getElementById('audio-text');\n    if (audioBtn) {\n      audioBtn.onclick = () => {\n        soundEnabled = !soundEnabled;\n        if (soundEnabled) {\n          audioIcon.textContent = 'volume_up';\n          audioText.textContent = 'Audio ON';\n          audioBtn.classList.remove('opacity-60');\n          emitSound('wood-thud');\n        } else {\n          audioIcon.textContent = 'volume_off';\n          audioText.textContent = 'Silencio';\n          audioBtn.classList.add('opacity-60');\n        }\n      };\n    }\n\n        /* las tarjetas se enlazan en bootPulgarcito */\n\n    const crossBtn = document.getElementById('btn-cross-expedition');\n    if (crossBtn) {\n      crossBtn.onclick = (e) => {\n        e.preventDefault();\n        handleCrossClick();\n      };\n      crossBtn.addEventListener('pointerdown', () => {\n        initAudio();\n      });\n    }\n  }\n\n  document.addEventListener('DOMContentLoaded', setupEventListeners);\n  window.addEventListener('load', setupEventListeners);\n\n  // Confetti & Star Sparkles Generator\n  function launchConfetti() {\n    const box = document.getElementById('confetti-box');\n    if (!box) return;\n    box.innerHTML = '';\n    const colors = ['#e74c3c', '#f1c40f', '#2ecc71', '#3498db', '#e67e22', '#9b59b6', '#ffd700', '#ffffff'];\n    for (let i = 0; i < 75; i++) {\n      const piece = document.createElement('div');\n      piece.className = 'confetti-piece';\n      piece.style.left = (Math.random() * 96 + 2) + '%';\n      piece.style.top = (Math.random() * 20) + '%';\n      piece.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];\n      piece.style.borderRadius = Math.random() > 0.5 ? '50%' : '2px';\n      piece.style.animationDelay = (Math.random() * 0.8) + 's';\n      box.appendChild(piece);\n    }\n    for (let j = 0; j < 14; j++) {\n      const star = document.createElement('span');\n      star.className = 'sparkle-dot text-amber-300 text-2xl font-bold select-none';\n      star.innerHTML = '✨';\n      star.style.right = (8 + Math.random() * 24) + '%';\n      star.style.bottom = (140 + Math.random() * 130) + 'px';\n      star.style.animationDelay = (j * 0.15) + 's';\n      box.appendChild(star);\n    }\n    setTimeout(() => { if (box) box.innerHTML = ''; }, 4500);\n  }\n\n  // Update Fixed Pedagogical Explanation Bar\n  function setExplanationBar(type, badge, text) {\n    const box = document.getElementById('cliff-explanation-bar');\n    const badgeEl = document.getElementById('explanation-badge');\n    const textEl = document.getElementById('explanation-text');\n    const iconEl = document.getElementById('explanation-icon');\n    const iconWrapper = document.getElementById('explanation-icon-wrapper');\n    const subtagEl = document.getElementById('explanation-subtag');\n\n    if (!box || !badgeEl || !textEl || !iconEl || !iconWrapper) return;\n\n    badgeEl.textContent = badge;\n    textEl.innerHTML = text;\n\n    box.className = 'w-full mt-2.5 rounded-2xl p-3.5 transition-all duration-300 border-2 flex items-center gap-3.5 shadow-md relative z-20 ';\n    iconWrapper.className = 'w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-inner border ';\n\n    if (type === 'success') {\n      box.className += 'bg-emerald-50 border-emerald-600/70 text-emerald-950 ring-2 ring-emerald-400/40';\n      iconWrapper.className += 'bg-emerald-200/90 border-emerald-400 text-emerald-900';\n      iconEl.textContent = '🎉';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-emerald-800';\n      if (subtagEl) subtagEl.textContent = '¡Cruce Exitoso!';\n    } else if (type === 'short-fail') {\n      box.className += 'bg-amber-50 border-amber-600/70 text-amber-950 ring-2 ring-amber-400/40';\n      iconWrapper.className += 'bg-amber-200/90 border-amber-400 text-amber-900';\n      iconEl.textContent = '⚠️';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-amber-800';\n      if (subtagEl) subtagEl.textContent = 'Fallo por Falta de Suelo';\n    } else if (type === 'no-bridge-fail') {\n      box.className += 'bg-red-50 border-red-600 text-red-950 ring-4 ring-red-400/40 animate-pulse';\n      iconWrapper.className += 'bg-red-200 border-red-400 text-red-900';\n      iconEl.textContent = '🚫';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-red-700';\n      if (subtagEl) subtagEl.textContent = 'Sin Puente Colocado';\n    } else if (type === 'long-fail') {\n      box.className += 'bg-rose-50 border-rose-600/70 text-rose-950 ring-2 ring-rose-400/40';\n      iconWrapper.className += 'bg-rose-200/90 border-rose-400 text-rose-900';\n      iconEl.textContent = '💥';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-rose-800';\n      if (subtagEl) subtagEl.textContent = 'Fallo por Inclinación Diagonal';\n    } else if (type === 'selected') {\n      box.className += 'bg-parchment-deep/80 border-brass-dark/60 text-ink ring-1 ring-brass/30';\n      iconWrapper.className += 'bg-parchment border-leather-med/40 text-leather-dark';\n      iconEl.textContent = '🪵';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-leather-warm';\n      if (subtagEl) subtagEl.textContent = 'Madera en posición';\n    } else {\n      box.className += 'bg-parchment border-leather-med/30 text-ink';\n      iconWrapper.className += 'bg-parchment-deep border-leather-med/40 text-leather-dark';\n      iconEl.textContent = '📋';\n      badgeEl.className = 'font-vintage text-xs uppercase tracking-wider font-extrabold text-leather-warm';\n      if (subtagEl) subtagEl.textContent = 'Explicación en tiempo real';\n    }\n  }\n\n  // Plank Selection Interaction: Visual differentiation of sizes\n\n\n  function boardScale() {\n    const match = (document.body.style.transform || '').match(/scale\\(([-\\d.]+)\\)/);\n    const scale = match ? parseFloat(match[1]) : 1;\n    return scale > 0.05 ? scale : 1;\n  }\n\n  function calculateWalkTargets() {\n    const stageEl = document.getElementById('adventure-stage');\n    const charEl = document.getElementById('pulgarcito-char');\n    const tentEl = document.getElementById('tent-camp');\n    const slotEl = document.getElementById('bridge-slot');\n    const scale = boardScale();\n    const local = (px) => px / scale;\n    const charRect = charEl ? charEl.getBoundingClientRect() : { left: 0 };\n    const tentRect = tentEl ? tentEl.getBoundingClientRect() : { left: 800 };\n    const slotRect = slotEl ? slotEl.getBoundingClientRect() : { left: 400, width: 400 };\n    const edgeDistance = Math.max(90, Math.round(local(slotRect.left - charRect.left) - 15));\n    const plank5TipDistance = Math.max(160, Math.round(local(slotRect.left + (slotRect.width * 0.5) - charRect.left) - 35));\n    const plank15ClimbDistance = Math.max(180, Math.round(local(slotRect.left + (slotRect.width * 0.6) - charRect.left)));\n    let campBDistance = Math.max(340, Math.round(local(tentRect.left - charRect.left) - 40));\n    if (stageEl && charRect) {\n      const stageRect = stageEl.getBoundingClientRect();\n      const idealTargetX = stageRect.left + (stageRect.width * 0.79);\n      campBDistance = Math.round(local(idealTargetX - charRect.left));\n    }\n    return { edgeDistance, totalDistance: campBDistance, plank5TipDistance, plank15ClimbDistance };\n  }\n\n  function startWalkingAnimation() {\n    setCharacterSprite('walking');\n    const bobber = document.getElementById('pulgarcito-bobber');\n    if (bobber) bobber.classList.add('walking-bob');\n  }\n\n  function stopWalkingAnimation() {\n    const bobber = document.getElementById('pulgarcito-bobber');\n    if (bobber) bobber.classList.remove('walking-bob');\n  }\n\n  let levelIndex = 0;\n  let selectedPlanks = [];\n\n  const LEVELS = [\n    {\n      gap: 10,\n      pick: 1,\n      title: '¡Rescata a Pulgarcito cruzando la grieta de 10 cm!',\n      subtitle: '• Paso de Roca 10 cm',\n      task: 'Toca la madera con la medida exacta para cubrir los <strong class=\"text-leather-dark underline decoration-brass\">10 cm</strong>:',\n      advice: 'Observa la distancia de 10 cm y elige la madera que no deje huecos ni sobrepase la roca.',\n      planks: [\n        { id: 'p5', name: 'Tablilla de Pino', size: 5, hint: 'Quedará hueco de 5 cm', sample: '¡Le falta la mitad!' },\n        { id: 'c10', name: 'Tablón de Cedro', size: 10, hint: '¡Calza exacta sin faltar ni sobrar!', sample: '⭐ 10 cm (Horizontal Exacta)', badge: 'Medida Exacta' },\n        { id: 'r15', name: 'Viga Maciza de Roble', size: 15, hint: 'Queda inclinada en diagonal y muy empinada', sample: '15 cm (Sobresale 5 cm)' }\n      ]\n    },\n    {\n      gap: 20,\n      pick: 2,\n      title: '¡Suma dos tablas para cruzar la grieta de 20 cm!',\n      subtitle: '• Paso de Roca 20 cm',\n      task: 'Selecciona <strong class=\"text-leather-dark\">2 tablas</strong> que sumen exactamente <strong class=\"text-leather-dark underline decoration-brass\">20 cm</strong>:',\n      advice: 'Suma dos medidas. La grieta mide 20 cm: ni menos ni más.',\n      planks: [\n        { id: 'p5', name: 'Tablilla de Pino', size: 5, hint: 'Mide 5 cm', sample: '5 cm' },\n        { id: 'a8', name: 'Listón de Abeto', size: 8, hint: 'Mide 8 cm', sample: '8 cm' },\n        { id: 'c12', name: 'Tablón de Cedro', size: 12, hint: 'Mide 12 cm', sample: '12 cm' },\n        { id: 'r15', name: 'Viga de Roble', size: 15, hint: 'Mide 15 cm', sample: '15 cm' }\n      ]\n    },\n    {\n      gap: 30,\n      pick: 2,\n      title: '¡La grieta creció a 30 cm!',\n      subtitle: '• Paso de Roca 30 cm',\n      task: 'Selecciona <strong class=\"text-leather-dark\">2 tablas</strong> que sumen exactamente <strong class=\"text-leather-dark underline decoration-brass\">30 cm</strong>:',\n      advice: 'Suma las medidas antes de cruzar. La grieta ahora es de 30 cm.',\n      planks: [\n        { id: 'p10', name: 'Tablilla de Pino', size: 10, hint: 'Mide 10 cm', sample: '10 cm' },\n        { id: 'a12', name: 'Listón de Abeto', size: 12, hint: 'Mide 12 cm', sample: '12 cm' },\n        { id: 'n15', name: 'Tabla de Nogal', size: 15, hint: 'Mide 15 cm', sample: '15 cm' },\n        { id: 'c18', name: 'Tablón de Cedro', size: 18, hint: 'Mide 18 cm', sample: '18 cm' },\n        { id: 'r20', name: 'Viga de Roble', size: 20, hint: 'Mide 20 cm', sample: '20 cm' }\n      ]\n    },\n    {\n      gap: 30,\n      pick: 3,\n      title: '¡Ahora hacen falta 3 tablas para 30 cm!',\n      subtitle: '• Paso de Roca 30 cm',\n      task: 'Selecciona <strong class=\"text-leather-dark\">3 tablas</strong> que sumen exactamente <strong class=\"text-leather-dark underline decoration-brass\">30 cm</strong>:',\n      advice: 'Junta tres medidas hasta llegar justo a 30 cm.',\n      planks: [\n        { id: 'p5', name: 'Tablilla de Pino', size: 5, hint: 'Mide 5 cm', sample: '5 cm' },\n        { id: 'a8', name: 'Listón de Abeto', size: 8, hint: 'Mide 8 cm', sample: '8 cm' },\n        { id: 'n10', name: 'Tabla de Nogal', size: 10, hint: 'Mide 10 cm', sample: '10 cm' },\n        { id: 'c12', name: 'Tablón de Cedro', size: 12, hint: 'Mide 12 cm', sample: '12 cm' },\n        { id: 'r15', name: 'Viga de Roble', size: 15, hint: 'Mide 15 cm', sample: '15 cm' }\n      ]\n    },\n    {\n      gap: 40,\n      pick: 3,\n      title: '¡Expedición final: 3 tablas que sumen 40 cm!',\n      subtitle: '• Paso de Roca 40 cm',\n      task: 'Selecciona <strong class=\"text-leather-dark\">3 tablas</strong> que sumen exactamente <strong class=\"text-leather-dark underline decoration-brass\">40 cm</strong>:',\n      advice: 'Último paso. Cuidado con las sumas que se pasan por pocos centímetros.',\n      planks: [\n        { id: 'p8', name: 'Tablilla de Pino', size: 8, hint: 'Mide 8 cm', sample: '8 cm' },\n        { id: 'a10', name: 'Listón de Abeto', size: 10, hint: 'Mide 10 cm', sample: '10 cm' },\n        { id: 'n12', name: 'Tabla de Nogal', size: 12, hint: 'Mide 12 cm', sample: '12 cm' },\n        { id: 'c14', name: 'Tablón de Cedro', size: 14, hint: 'Mide 14 cm', sample: '14 cm' },\n        { id: 'r18', name: 'Viga de Roble', size: 18, hint: 'Mide 18 cm', sample: '18 cm' }\n      ]\n    }\n  ];\n\n  function currentLevel() {\n    return LEVELS[levelIndex];\n  }\n\n  function selectedSum() {\n    return selectedPlanks.reduce((total, plank) => total + plank.size, 0);\n  }\n\n  function woodClass(size, gap) {\n    const ratio = size / gap;\n    if (ratio < 0.7) return 'plank-wood-5';\n    if (ratio <= 1.05) return 'plank-wood-10';\n    return 'plank-wood-15';\n  }\n\n  function showButton(button, visible) {\n    if (!button) return;\n    if (visible) {\n      button.classList.remove('hidden');\n      button.style.display = 'inline-flex';\n    } else {\n      button.classList.add('hidden');\n      button.style.display = 'none';\n    }\n  }\n\n  function applyLevelChrome() {\n    const level = currentLevel();\n    const field = document.getElementById('field-number');\n    const subtitle = document.getElementById('level-subtitle');\n    const title = document.getElementById('level-title');\n    const banner = document.getElementById('gap-banner');\n    const label = document.getElementById('gap-label');\n    const count = document.getElementById('rack-count');\n    const hint = document.getElementById('rack-hint');\n    const advice = document.getElementById('advice-text');\n    if (field) field.textContent = 'Cuaderno de Campo Nº ' + (102 + levelIndex);\n    if (subtitle) subtitle.textContent = level.subtitle;\n    if (title) title.textContent = level.title;\n    if (banner) banner.textContent = level.gap + ' cm EXACTOS';\n    if (label) label.textContent = level.gap + ' cm exactos';\n    if (count) count.textContent = level.planks.length + ' Maderas Disponibles';\n    if (hint) hint.innerHTML = level.task;\n    if (advice) advice.innerHTML = '<span class=\"text-leather-warm font-bold\">Consejo:</span> ' + level.advice;\n  }\n\n  function renderCards() {\n    const grid = document.getElementById('plank-grid');\n    const level = currentLevel();\n    if (!grid) return;\n    grid.innerHTML = level.planks.map((plank, index) => {\n      const selected = selectedPlanks.some((item) => item.id === plank.id);\n      const klass = woodClass(plank.size, level.gap);\n      const width = Math.max(18, Math.min(100, Math.round((plank.size / level.gap) * 100)));\n      const badge = plank.badge\n        ? '<div class=\"absolute -top-2.5 right-4 bg-gradient-to-r from-brass to-amber-400 text-leather-dark font-vintage text-sm font-black px-2.5 py-1 rounded-full border border-leather-dark shadow-md pointer-events-none\">⭐ ' + plank.badge + '</div>'\n        : '';\n      return '<div class=\"plank-option group cursor-pointer rounded-2xl p-4 border-2 shadow-md hover:shadow-xl hover:border-leather-dark transition-all flex flex-col justify-between gap-3 relative select-none ' +\n        (selected ? 'ring-4 ring-emerald-500 bg-emerald-100/80 border-emerald-700 shadow-2xl' : 'border-leather-med/50 bg-parchment') +\n        '\" data-plank-id=\"' + plank.id + '\">' + badge +\n        '<div class=\"flex items-center justify-between pointer-events-none\"><div class=\"flex items-center gap-2\"><span class=\"w-11 h-11 shrink-0 rounded-full bg-parchment-deep border border-leather-med text-leather-dark font-vintage text-xl font-black flex items-center justify-center\">' + (index + 1) + '</span><span>🪵</span><span class=\"font-bold text-sm sm:text-base text-leather-dark font-sans\">' + plank.name + '</span></div><span class=\"shrink-0 px-3 py-1 rounded-md bg-amber-100 border-2 border-amber-600 font-vintage text-2xl font-black text-amber-950\">' + plank.size + ' cm</span></div>' +\n        '<div class=\"w-full h-16 bg-[#ebd2b5]/70 rounded-xl p-2 flex items-center border border-leather-med/30 pointer-events-none overflow-visible\"><div class=\"' + klass + ' h-full rounded-lg border-2 border-[#5c3216] flex items-center justify-center text-lg sm:text-xl font-vintage font-black text-center leading-tight px-1\" style=\"width:' + width + '%\">' + plank.size + ' cm' + '</div></div>' +\n        '<div class=\"flex items-center justify-between text-base sm:text-lg font-handwritten pt-1 border-t border-leather-med/20 pointer-events-none\"><span>' + plank.hint + '</span><span class=\"status-tag font-vintage font-bold text-leather-med\">' + (selected ? '✓ Seleccionada' : 'Elegir ➔') + '</span></div></div>';\n    }).join('');\n    requestAnimationFrame(fitGame);\n  }\n\n  function paintBridge() {\n    const level = currentLevel();\n    const board = document.getElementById('active-bridge-board');\n    const guide = document.getElementById('slot-guide-text');\n    const title = document.getElementById('active-board-title');\n    const stamp = document.getElementById('active-board-stamp');\n    if (!board || !title || !stamp) return;\n    board.classList.remove('hidden', 'plank-wood-5', 'plank-wood-10', 'plank-wood-15', 'plank-abyss-fall', 'ring-4', 'ring-brass', 'shadow-[0_0_35px_#d8a63f]');\n    board.style.opacity = '1';\n    if (!selectedPlanks.length) {\n      board.classList.add('hidden');\n      board.style.width = '0%';\n      board.style.transform = 'rotate(0deg)';\n      if (guide) guide.classList.remove('hidden');\n      return;\n    }\n    if (guide) guide.classList.add('hidden');\n    const sum = selectedSum();\n    const ratio = sum / level.gap;\n    const tooLong = sum > level.gap;\n    board.classList.add(tooLong ? 'plank-wood-15' : sum === level.gap ? 'plank-wood-10' : 'plank-wood-5');\n    board.style.width = Math.min(ratio * 100, 155) + '%';\n    board.style.transform = tooLong ? 'rotate(-21deg) translate(0px, 4px)' : 'rotate(0deg)';\n    title.textContent = selectedPlanks.map((plank) => plank.size + ' cm').join(' + ');\n    stamp.textContent = sum === level.gap && selectedPlanks.length === level.pick\n      ? '⭐ ' + sum + ' cm exactos'\n      : sum + ' cm';\n    stamp.className = 'px-2 py-1 rounded text-sm sm:text-base font-bold ' + (sum === level.gap ? 'bg-emerald-500 text-white' : tooLong ? 'bg-rose-700 text-white' : 'bg-amber-200 text-leather-dark');\n  }\n\n  function choosePlankId(id) {\n    if (isMoving) return;\n    if (hasWon) resetExpedition(true);\n    if (autoResetTimer) {\n      clearTimeout(autoResetTimer);\n      autoResetTimer = null;\n    }\n    const level = currentLevel();\n    const plank = level.planks.find((item) => item.id === id);\n    if (!plank) return;\n    const exists = selectedPlanks.some((item) => item.id === id);\n    if (exists) {\n      selectedPlanks = selectedPlanks.filter((item) => item.id !== id);\n    } else if (level.pick === 1) {\n      selectedPlanks = [plank];\n    } else if (selectedPlanks.length >= level.pick) {\n      setExplanationBar('selected', 'Ya elegiste ' + level.pick + ' tablas', 'Quita una tabla si quieres cambiar la suma. La grieta mide ' + level.gap + ' cm.');\n      return;\n    } else {\n      selectedPlanks = selectedPlanks.concat(plank);\n    }\n    emitSound('wood-thud');\n    renderCards();\n    paintBridge();\n    const sum = selectedSum();\n    const formula = selectedPlanks.map((item) => item.size + ' cm').join(' + ') || '0 cm';\n    if (!selectedPlanks.length) {\n      setExplanationBar('default', 'Informe de Expedición', level.pick === 1\n        ? 'Selecciona una madera y luego pulsa <strong>\"Cruzar Expedición\"</strong>.'\n        : 'Selecciona ' + level.pick + ' tablas que sumen ' + level.gap + ' cm.');\n    } else if (selectedPlanks.length < level.pick) {\n      setExplanationBar('selected', 'Suma parcial: ' + sum + ' cm', formula + ' = ' + sum + ' cm. Todavía faltan tablas por elegir. La grieta mide ' + level.gap + ' cm.');\n    } else if (sum === level.gap) {\n      emitSound('sparkle');\n      setExplanationBar('selected', 'Suma exacta: ' + sum + ' cm', formula + ' = ' + level.gap + ' cm. Pulsa <strong>\"Cruzar Expedición\"</strong>.');\n    } else if (sum < level.gap) {\n      setExplanationBar('selected', 'Todavía falta longitud', formula + ' = ' + sum + ' cm. Faltan ' + (level.gap - sum) + ' cm para cubrir la grieta.');\n    } else {\n      setExplanationBar('selected', 'La suma se pasa', formula + ' = ' + sum + ' cm. Sobran ' + (sum - level.gap) + ' cm y la tabla queda inclinada.');\n    }\n    const crossBtn = document.getElementById('btn-cross-expedition');\n    if (crossBtn && selectedPlanks.length === level.pick) {\n      crossBtn.classList.add('ring-4', 'ring-amber-400', 'animate-pulse');\n    }\n  }\n\n  function tipDistance(ratio) {\n    const charEl = document.getElementById('pulgarcito-char');\n    const slotEl = document.getElementById('bridge-slot');\n    const charRect = charEl.getBoundingClientRect();\n    const slotRect = slotEl.getBoundingClientRect();\n    return Math.max(90, Math.round((slotRect.left + (slotRect.width * ratio) - charRect.left) / boardScale() - 35));\n  }\n\n  function failAndReset(delay) {\n    autoResetTimer = setTimeout(() => resetExpedition(true), delay);\n  }\n\n  function handleCrossClick() {\n    if (isMoving || hasWon) return;\n    const level = currentLevel();\n    const pulgarcito = document.getElementById('pulgarcito-char');\n    const board = document.getElementById('active-bridge-board');\n    const crossBtn = document.getElementById('btn-cross-expedition');\n    const sum = selectedSum();\n    const formula = selectedPlanks.map((item) => item.size + ' cm').join(' + ');\n\n    if (selectedPlanks.length > 0 && selectedPlanks.length < level.pick) {\n      setExplanationBar('selected', 'Faltan tablas', 'Tienes que elegir ' + level.pick + ' tablas. Llevas ' + sum + ' cm y la grieta mide ' + level.gap + ' cm.');\n      return;\n    }\n\n    isMoving = true;\n    if (crossBtn) {\n      crossBtn.disabled = true;\n      crossBtn.classList.remove('animate-pulse');\n      crossBtn.classList.add('opacity-50');\n    }\n\n    pulgarcito.style.transition = 'none';\n    pulgarcito.style.transform = 'translate3d(0px, 0px, 0px) scale(1)';\n    pulgarcito.style.opacity = '1';\n    pulgarcito.classList.remove('char-victory-dance', 'char-abyss-fall', 'char-slip-fall');\n\n    const targets = calculateWalkTargets();\n\n    if (!selectedPlanks.length) {\n      startWalkingAnimation();\n      walkAnimationInterval = setInterval(() => emitSound('step'), 230);\n      pulgarcito.style.transition = 'transform 0.85s linear';\n      pulgarcito.style.transform = 'translate3d(' + targets.edgeDistance + 'px, 0px, 0px)';\n      setTimeout(() => {\n        clearInterval(walkAnimationInterval);\n        stopWalkingAnimation();\n        emitSound('comic-slip');\n        setCharacterSprite('falling');\n        setExplanationBar('no-bridge-fail', '¡Sin puente!', 'No colocaste ninguna madera. Pulgarcito intentó cruzar y cayó al abismo.');\n        pulgarcito.style.setProperty('--fall-x', targets.edgeDistance + 'px');\n        pulgarcito.style.setProperty('--fall-y', '0px');\n        pulgarcito.classList.add('char-slip-fall');\n        setTimeout(() => emitSound('splash'), 650);\n      }, 900);\n      failAndReset(2500);\n      return;\n    }\n\n    if (sum < level.gap) {\n      const distance = tipDistance(sum / level.gap);\n      startWalkingAnimation();\n      walkAnimationInterval = setInterval(() => emitSound('step'), 230);\n      pulgarcito.style.transition = 'transform 1.35s linear';\n      pulgarcito.style.transform = 'translate3d(' + distance + 'px, 0px, 0px)';\n      setTimeout(() => {\n        clearInterval(walkAnimationInterval);\n        stopWalkingAnimation();\n        setCharacterSprite('falling');\n        emitSound('fall-whoosh');\n        setExplanationBar('short-fail', '¡Faltó longitud!', formula + ' = ' + sum + ' cm. No cubre la grieta de ' + level.gap + ' cm y Pulgarcito cae al abismo.');\n        pulgarcito.style.setProperty('--fall-x', distance + 'px');\n        pulgarcito.style.setProperty('--fall-y', '0px');\n        pulgarcito.classList.add('char-abyss-fall');\n        setTimeout(() => emitSound('splash'), 700);\n      }, 1400);\n      failAndReset(2800);\n      return;\n    }\n\n    if (sum > level.gap) {\n      startWalkingAnimation();\n      walkAnimationInterval = setInterval(() => emitSound('step'), 230);\n      pulgarcito.style.transition = 'transform 1.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)';\n      pulgarcito.style.transform = 'translate3d(' + targets.plank15ClimbDistance + 'px, -46px, 0px) rotate(-14deg)';\n      setTimeout(() => {\n        clearInterval(walkAnimationInterval);\n        stopWalkingAnimation();\n        emitSound('wood-crack');\n        if (board) board.classList.add('plank-abyss-fall');\n        setCharacterSprite('falling');\n        setExplanationBar('long-fail', '¡Demasiado larga e inclinada!', formula + ' = ' + sum + ' cm. Sobran ' + (sum - level.gap) + ' cm, la tabla queda en diagonal y Pulgarcito se resbala.');\n        pulgarcito.style.setProperty('--fall-x', targets.plank15ClimbDistance + 'px');\n        pulgarcito.style.setProperty('--fall-y', '-46px');\n        pulgarcito.classList.add('char-abyss-fall');\n        emitSound('fall-whoosh');\n        setTimeout(() => emitSound('splash'), 700);\n      }, 1550);\n      failAndReset(3000);\n      return;\n    }\n\n    startWalkingAnimation();\n    walkAnimationInterval = setInterval(() => emitSound('step'), 230);\n    pulgarcito.style.transition = 'transform 2.4s linear';\n    pulgarcito.style.transform = 'translate3d(' + targets.totalDistance + 'px, 0px, 0px)';\n    setTimeout(() => {\n      clearInterval(walkAnimationInterval);\n      stopWalkingAnimation();\n      setCharacterSprite('celebrating');\n      hasWon = true;\n      isMoving = false;\n      if (autoResetTimer) {\n        clearTimeout(autoResetTimer);\n        autoResetTimer = null;\n      }\n      emitSound('victory');\n      const stageEl = document.getElementById('adventure-stage');\n      const stageWidth = stageEl ? stageEl.clientWidth : 1000;\n      const finalLeftPercent = Math.min(84, Math.max(68, Math.round(((35 + targets.totalDistance) / stageWidth) * 100)));\n      pulgarcito.style.transition = 'none';\n      pulgarcito.style.left = finalLeftPercent + '%';\n      pulgarcito.style.transform = 'translate3d(0px, 0px, 0px)';\n      pulgarcito.classList.add('char-victory-dance');\n      if (board) board.classList.add('ring-4', 'ring-brass', 'shadow-[0_0_35px_#d8a63f]');\n      launchConfetti();\n      const last = levelIndex === LEVELS.length - 1;\n      setExplanationBar('success', last ? '¡Expedición completa!' : '¡Misión cumplida!', last\n        ? formula + ' = ' + level.gap + ' cm. Pulgarcito cruzó los 5 pasos y llegó al campamento.'\n        : formula + ' = ' + level.gap + ' cm. La medida es exacta y Pulgarcito llegó al campamento.');\n      showButton(crossBtn, false);\n      if (last) {\n        showButton(document.getElementById('btn-next-level'), false);\n        showButton(document.getElementById('btn-restart-action'), false);\n        showButton(document.getElementById('btn-replay-all'), true);\n        showButton(document.getElementById('btn-go-home'), true);\n      } else {\n        showButton(document.getElementById('btn-next-level'), true);\n        showButton(document.getElementById('btn-restart-action'), true);\n      }\n    }, 2450);\n  }\n\n  function goToNextLevel() {\n    if (levelIndex >= LEVELS.length - 1) return;\n    emitSound('sparkle');\n    levelIndex += 1;\n    resetExpedition(true);\n    applyLevelChrome();\n    renderCards();\n    setExplanationBar('default', 'Informe de Expedición', currentLevel().pick === 1\n      ? 'Nuevo paso. Elige la madera de ' + currentLevel().gap + ' cm y pulsa <strong>\"Cruzar Expedición\"</strong>.'\n      : 'Nuevo paso. Elige ' + currentLevel().pick + ' tablas que sumen ' + currentLevel().gap + ' cm.');\n  }\n\n  function replayAll() {\n    levelIndex = 0;\n    resetExpedition(true);\n    applyLevelChrome();\n    renderCards();\n    setExplanationBar('default', 'Informe de Expedición', 'Selecciona una de las maderas de abajo y luego pulsa <strong>\"Cruzar Expedición\"</strong>.');\n  }\n\n  function goHome() {\n    window.parent.postMessage({ type: 'pulgarcito-home' }, '*');\n  }\n\n  function resetExpedition(isAuto) {\n    if (autoResetTimer) {\n      clearTimeout(autoResetTimer);\n      autoResetTimer = null;\n    }\n    isMoving = false;\n    hasWon = false;\n    selectedPlanks = [];\n    if (walkAnimationInterval) {\n      clearInterval(walkAnimationInterval);\n      walkAnimationInterval = null;\n    }\n    stopWalkingAnimation();\n    const confBox = document.getElementById('confetti-box');\n    if (confBox) confBox.innerHTML = '';\n    const pulgarcito = document.getElementById('pulgarcito-char');\n    if (pulgarcito) {\n      pulgarcito.style.opacity = '0';\n      pulgarcito.style.transition = 'none';\n      pulgarcito.classList.remove('char-victory-dance', 'char-abyss-fall', 'char-slip-fall');\n      pulgarcito.style.transform = 'translate3d(0px, 0px, 0px) scale(1)';\n      pulgarcito.style.left = '35px';\n      setCharacterSprite('standing');\n      void pulgarcito.offsetHeight;\n      requestAnimationFrame(() => { pulgarcito.style.opacity = '1'; });\n    }\n    paintBridge();\n    renderCards();\n    const crossBtn = document.getElementById('btn-cross-expedition');\n    if (crossBtn) {\n      crossBtn.disabled = false;\n      crossBtn.classList.remove('ring-4', 'ring-amber-400', 'animate-pulse', 'opacity-50');\n      showButton(crossBtn, true);\n    }\n    showButton(document.getElementById('btn-restart-action'), false);\n    showButton(document.getElementById('btn-next-level'), false);\n    showButton(document.getElementById('btn-replay-all'), false);\n    showButton(document.getElementById('btn-go-home'), false);\n    if (!isAuto) {\n      emitSound('wood-thud');\n      const level = currentLevel();\n      setExplanationBar('default', 'Informe de Expedición', level.pick === 1\n        ? 'Selecciona una madera y luego pulsa <strong>\"Cruzar Expedición\"</strong>.'\n        : 'Selecciona ' + level.pick + ' tablas que sumen ' + level.gap + ' cm.');\n    }\n  }\n\n\n  function fitGame() {\n    const root = document.body;\n    const touchLayout = window.matchMedia('(pointer: coarse), (max-width: 1100px)').matches;\n    const maxW = Math.min(window.innerWidth - (touchLayout ? 12 : 40), 1760);\n    root.style.transform = 'none';\n    root.style.width = maxW + 'px';\n    root.style.marginLeft = '0px';\n    root.style.marginBottom = '0px';\n    const height = root.scrollHeight;\n    const fit = Math.min(1, window.innerHeight / Math.max(height, 1));\n    // En telefonos y tabletas no se encoge: encogerlo dejaria letras de 5 px.\n    const scale = touchLayout ? 1 : fit;\n    const useScale = scale < 0.995;\n    root.style.transformOrigin = 'top center';\n    root.style.transform = useScale ? 'scale(' + scale + ')' : 'none';\n    root.style.marginLeft = Math.max(0, (window.innerWidth - maxW) / 2) + 'px';\n    const visualHeight = height * scale;\n    const needsScroll = visualHeight > window.innerHeight + 2;\n    const html = document.documentElement;\n    // La hoja de estilos usa !important, asi que aqui tambien hace falta.\n    if (touchLayout) {\n      html.style.setProperty('height', '100%', 'important');\n      html.style.setProperty('overflow', 'hidden', 'important');\n      root.style.setProperty('height', '100%', 'important');\n      root.style.setProperty('min-height', '0', 'important');\n      root.style.setProperty('max-height', '100%', 'important');\n      root.style.setProperty('overflow-x', 'hidden', 'important');\n      root.style.setProperty('overflow-y', 'auto', 'important');\n      root.style.setProperty('-webkit-overflow-scrolling', 'touch');\n      root.style.touchAction = 'pan-y';\n      root.style.overscrollBehaviorY = 'contain';\n    } else {\n      html.style.setProperty('overflow-y', needsScroll ? 'auto' : 'hidden', 'important');\n      html.style.setProperty('height', needsScroll ? 'auto' : '100%', 'important');\n      if (needsScroll && useScale) root.style.marginBottom = -(height - visualHeight) + 'px';\n    }\n    alignPlankToCliffs();\n  }\n\n  let cliffGreenRows = null;\n  function cliffGreenRowsFor(img) {\n    if (cliffGreenRows) return cliffGreenRows;\n    const canvas = document.createElement('canvas');\n    canvas.width = img.naturalWidth;\n    canvas.height = img.naturalHeight;\n    const ctx = canvas.getContext('2d');\n    ctx.drawImage(img, 0, 0);\n    const w = canvas.width;\n    const h = canvas.height;\n    const data = ctx.getImageData(0, 0, w, h).data;\n    const rows = new Array(h);\n    for (let y = 0; y < h; y++) {\n      let found = 0;\n      const row = y * w * 4;\n      for (let x = w - 1; x >= 0; x -= 2) {\n        const i = row + x * 4;\n        if (data[i + 3] < 24) continue;\n        const r = data[i];\n        const g = data[i + 1];\n        const b = data[i + 2];\n        if (g > r + 12 && g > b + 12 && g > 70) { found = x; break; }\n      }\n      rows[y] = found;\n    }\n    cliffGreenRows = { rows: rows, w: w, h: h };\n    return cliffGreenRows;\n  }\n\n  function grassTipRatio(img) {\n    const profile = cliffGreenRowsFor(img);\n    const boxW = img.clientWidth || 1;\n    const boxH = img.clientHeight || 1;\n    const cover = Math.max(boxW / profile.w, boxH / profile.h);\n    const srcY0 = Math.max(0, Math.round((profile.h * cover - boxH) / cover));\n    const srcX0 = 0;\n    const srcX1 = srcX0 + boxW / cover;\n    let tip = 0;\n    for (let y = srcY0; y < profile.h; y++) {\n      if (profile.rows[y] > tip) tip = profile.rows[y];\n    }\n    const visibleTip = Math.min(Math.max(tip, srcX0), srcX1);\n    return (visibleTip - srcX0) / Math.max(1, srcX1 - srcX0);\n  }\n\n  function alignPlankToCliffs() {\n    const zone = document.getElementById('bridge-zone');\n    const slot = document.getElementById('bridge-slot');\n    const leftImg = document.querySelector('#cliff-a-zone img');\n    const rightImg = document.querySelector('#cliff-b-zone img');\n    if (!zone || !slot || !leftImg || !rightImg || !leftImg.naturalWidth || !rightImg.naturalWidth) return;\n    const measure = zone.children[0];\n    zone.style.minWidth = '0px';\n    [measure, slot].forEach((el) => {\n      if (!el) return;\n      el.style.alignSelf = 'flex-start';\n      el.style.position = 'relative';\n      el.style.left = '0px';\n      el.style.marginLeft = '0px';\n      el.style.width = '100%';\n      el.style.maxWidth = 'none';\n    });\n    const ratio = grassTipRatio(leftImg);\n    const leftBox = leftImg.getBoundingClientRect();\n    const rightBox = rightImg.getBoundingClientRect();\n    const zoneBox = zone.getBoundingClientRect();\n    const scale = boardScale();\n    const overlap = 12 * scale;\n    const leftTip = leftBox.left + ratio * leftBox.width - overlap;\n    const rightTip = rightBox.right - ratio * rightBox.width + overlap;\n    const leftPx = (leftTip - zoneBox.left) / scale;\n    const widthPx = Math.max(40, (rightTip - leftTip) / scale);\n    [measure, slot].forEach((el) => {\n      if (!el) return;\n      el.style.marginLeft = leftPx + 'px';\n      el.style.width = widthPx + 'px';\n    });\n  }\n\n  let pulgarcitoReady = false;\n  function bootPulgarcito() {\n    if (pulgarcitoReady && document.querySelector('[data-plank-id]')) return;\n    pulgarcitoReady = true;\n    const grid = document.getElementById('plank-grid');\n    if (grid && !grid.dataset.bound) {\n      grid.dataset.bound = '1';\n      grid.addEventListener('click', (event) => {\n        const card = event.target.closest('[data-plank-id]');\n        if (!card) return;\n        initAudio();\n        choosePlankId(card.dataset.plankId);\n      });\n    }\n    const replay = document.getElementById('btn-replay-all');\n    const home = document.getElementById('btn-go-home');\n    const next = document.getElementById('btn-next-level');\n    document.querySelectorAll('#cliff-a-zone img, #cliff-b-zone img').forEach((img) => {\n      img.addEventListener('load', alignPlankToCliffs);\n    });\n    alignPlankToCliffs();\n    if (replay) replay.onclick = replayAll;\n    if (home) home.onclick = goHome;\n    if (next) next.onclick = goToNextLevel;\n    applyLevelChrome();\n    resetExpedition(true);\n    setExplanationBar('default', 'Informe de Expedición', 'Selecciona una de las 3 maderas de abajo para colocarla sobre la grieta y luego pulsa <strong>\"Cruzar Expedición\"</strong>.');\n  }\n\n  document.addEventListener('DOMContentLoaded', bootPulgarcito);\n  window.addEventListener('load', bootPulgarcito);\n  window.addEventListener('resize', fitGame);\n  window.addEventListener('orientationchange', function () { setTimeout(fitGame, 200); });\n\n</script>\n\n\n\n\n</body></html>";

export default function RescataPulgarcitoGamePage() {
  const navigate = useNavigate();
  const { semanaId } = useParams();
  const frameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.source !== frameRef.current?.contentWindow) return;
      if (event.data?.type === 'pulgarcito-home') {
        navigate(`/semana/${semanaId ?? '1'}`);
      }
    };
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  }, [navigate, semanaId]);

  return (
    <div className="flex h-full min-h-0 w-full flex-col bg-[#211209]">
      <div className="flex shrink-0 items-center px-3 py-2">
        <KidBackButton
          onClick={() => navigate(`/semana/${semanaId ?? '1'}/rescata-pulgarcito`)}
          label="Volver al inicio del juego"
        />
      </div>
      <iframe
        ref={frameRef}
        title="Rescata a Pulgarcito"
        srcDoc={gameHtml}
        className="min-h-0 w-full flex-1 border-0 bg-[#211209]"
      />
    </div>
  );
}
